pub fn is_session_id(word: &str) -> bool {
    let hex = word.strip_prefix("session-").unwrap_or(word);
    if hex.len() != 32 || !hex.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f')) {
        return false;
    }
    let Ok(value) = u128::from_str_radix(hex, 16) else {
        return false;
    };
    value >= (1u128 << 64)
}

